package exercise
import("os";"os/exec";"plugin";"reflect";"strings";"testing";"opsforge.local/exercise/shared")
func TestPluginRealCompatibilityAndCache(t *testing.T){
 good,bad:=os.Getenv("GOOD_PLUGIN"),os.Getenv("BAD_PLUGIN");if good==""||bad==""||shared.Offset()!=1{t.Fatal("fixture")}
 fn,e:=Load(good,"Apply");if e!=nil||fn(9)!=10{t.Fatal("valid plugin",e)}
 p,e:=plugin.Open(good);if e!=nil{t.Fatal(e)};p2,e:=plugin.Open(good);if e!=nil||p2!=p{t.Fatal("same path not cached",e)}
 v,e:=p.Lookup("Count");if e!=nil||*v.(*int)!=1{t.Fatal("plugin initialized more than once",v,e)}
 fn,e=Load(good,"Missing");if e==nil||fn!=nil{t.Fatal("missing symbol treated as valid",e)}
 fn,e=Load(good,"Count");if e==nil||fn!=nil{t.Fatal("wrong symbol type treated as valid",e)}
 fn,e=Load(good+".missing","Apply");if e==nil||fn!=nil{t.Fatal("missing plugin treated as valid",e)}
 fn,e=Load(bad,"Apply");if e==nil||fn!=nil||!strings.Contains(e.Error(),"different version"){t.Fatal("incompatible shared package accepted",e)}
 if _,ok:=reflect.TypeOf(p).MethodByName("Close");ok{t.Fatal("unexpected plugin close method")}
 child:=exec.Command(os.Args[0],"-test.v","-test.run=^TestFreshProcess$");child.Env=append(os.Environ(),"OPSF_PLUGIN_CHILD=1");raw,e:=child.CombinedOutput();if e!=nil||!strings.Contains(string(raw),"FRESH_PROCESS_LOADED_PLUGIN_ONCE"){t.Fatal("fresh process recovery",e,string(raw))}
 t.Log("NATIVE_GO_PLUGIN_REAL_SHARED_VERSION_MISMATCH_SAME_PATH_CACHE_NO_CLOSE_AND_FRESH_PROCESS")
}
func TestFreshProcess(t *testing.T){
 if os.Getenv("OPSF_PLUGIN_CHILD")!="1"{return};fn,e:=Load(os.Getenv("GOOD_PLUGIN"),"Apply");if e!=nil||fn(4)!=5{t.Fatal(e)};p,e:=plugin.Open(os.Getenv("GOOD_PLUGIN"));if e!=nil{t.Fatal(e)};v,e:=p.Lookup("Count");if e!=nil||*v.(*int)!=1{t.Fatal(e)};t.Log("FRESH_PROCESS_LOADED_PLUGIN_ONCE")
}
